export async function addSkillToLock(
  s,
  entry,
  lockPath = getGlobalLockPath(),
) {
  const lock = await readLock(lockPath)
  const existing = lock.skills[s]

  const mergedAgents = existing?.agents
    ? [...new Set([...existing.agents, ...(entry.agents || [])])]
    : entry.agents || []

  pushHistory(lock, s, entry)

  const history = lock.skills[s]?.history || []

  lock.skills[s] = {
    ...entry,
    agents: mergedAgents,
    installedAt: new Date().toISOString(),
    history,
  }

  await writeLock(lock, lockPath)

  return lock
}
